func:
// 左の「ゲーム設定」の値を flow.config に入れる。
// 「ゲーム設定」を書き換えてデプロイすると、そのたびにここが動いて新しい値になる。
flow.set("config", msg.payload);

// ゲームの状態がまだなければ（Node-RED の起動直後）、空の状態をつくる
if (!flow.get("game")) {
    flow.set("game", {
        phase: "waiting",          // waiting / countdown / playing / finished
        phaseStartedAt: Date.now(), // 今の段階になった時刻 [ミリ秒]
        nextRank: 1,               // 次に割れた人の順位
        players: [],               // 参加者（配列の順番 = 画面のマスの位置）
    });
}

node.status({ fill: "green", shape: "dot", text: "しきい値 " + msg.payload.threshold + " / 不感帯 " + msg.payload.deadzone });
return null;

// 参加者の一覧を空にして、待機に戻す。
// 子機の名前を書き換えた人がいて、古い名前のマスが残ってしまったときなどに押す。
// （空にしても、子機からデータが届けばまた接続順に並ぶ）
const game = flow.get("game");
if (!game) return null;

game.players = [];
game.nextRank = 1;
game.phase = "waiting";
game.phaseStartedAt = Date.now();
flow.set("game", game);
return null;

// 子機の代わりにダミーのデータをつくる（子機がないときに画面を確かめる用）。
// 本物の子機と同じく、1人ずつ {"id":"ikai","p":3.2} を 1秒に10〜20回送る。
// 使うときは、左の「モック 0.05秒ごと」を有効にする（実機をつなぐときは無効に戻す）。

// ダミーの子機（10人未満の確認も兼ねて7人。color を送らない子機は Node-RED が色を割り当てる）
const DUMMY = [
    { id: "ikai", color: "#ff6699" },
    { id: "tanaka", color: "#33aaff" },
    { id: "suzuki" },
    { id: "sato" },
    { id: "takahashi", color: "#cc77ff" },
    { id: "ito" },
    { id: "watanabe" },
];

// 子機ごとの内部状態（送信回数・吹く強さはばらつかせる）
let kids = context.get("kids");
if (!kids) {
    kids = DUMMY.map(function (d) {
        return {
            id: d.id,
            color: d.color,
            rate: 10 + Math.random() * 10,     // 1秒あたりの送信回数
            strength: 2 + Math.random() * 6,   // 吹いたときの圧力 [kPa]
            blowing: false,
            nextAt: 0,
        };
    });
    context.set("kids", kids);
}

const now = Date.now();
const msgs = [];

kids.forEach(function (kid, i) {
    // 最後の1人は 30秒ごとに3秒間だけ送信を止める（通信切れの表示の確認用）
    if (i === kids.length - 1 && (now / 1000) % 30 > 27) return;

    // 送信の時刻になっていなければ送らない
    if (now < kid.nextAt) return;
    kid.nextAt = now + 1000 / kid.rate;

    // ときどき吹く・休むを切り替える
    if (Math.random() < 0.05) kid.blowing = !kid.blowing;
    const noise = (Math.random() - 0.5) * 0.6;
    const p = (kid.blowing ? kid.strength : 0) + noise;

    const payload = { id: kid.id, p: Math.round(p * 10) / 10 };
    if (kid.color) payload.color = kid.color;
    msgs.push({ topic: "handson/balloon/" + kid.id, payload: payload });
});

// 1つの出力から複数のメッセージを順に送る
return [msgs];

// 子機のデータ {"id":"ikai","p":3.2} を受け取り、その人の圧力を更新する。
// 計測中なら膨らみを足し込み、しきい値を超えたら割る（割れた順に順位を付ける）。
//   膨らみ += max(圧力 - 不感帯, 0) × 前回受信からの経過時間[秒]

// 通信が途切れたあとの1回で膨らみすぎないよう、経過時間はこの秒数までにする
const MAX_DT = 0.5;

// 子機から色が届かなかったときに割り当てる色（まだ誰も使っていない色を前から選ぶ）
const PALETTE = [
    "#ff6699", "#33aaff", "#ffcc33", "#66dd88", "#cc77ff",
    "#ff8844", "#44dddd", "#aaaaff", "#ff5555", "#bbdd44",
];

const config = flow.get("config");
const game = flow.get("game");
if (!config || !game) return null;

// ===== データの確認 =====
const data = msg.payload || {};
const id = typeof data.id === "string" ? data.id.trim() : "";
const p = Number(data.p);
if (id === "" || !Number.isFinite(p)) {
    node.warn("形式が違うデータを無視しました: " + JSON.stringify(data));
    return null;
}

const now = Date.now();

// ===== 参加者を探す（初めての子機なら末尾に追加 = 接続順にマスが並ぶ） =====
let player = game.players.find(function (pl) { return pl.id === id; });
if (!player) {
    if (game.players.length >= config.maxPlayers) {
        node.warn(config.maxPlayers + " 人を超えたため参加できません: " + id);
        return null;
    }
    const used = game.players.map(function (pl) { return pl.color; });
    const unused = PALETTE.find(function (c) { return used.indexOf(c) === -1; });
    player = {
        id: id,
        color: typeof data.color === "string" && data.color !== ""
            ? data.color
            : unused || PALETTE[game.players.length % PALETTE.length],
        p: 0,
        amount: 0,     // 足し込んだ膨らみ [kPa·秒]
        burst: false,
        rank: null,
        lastAt: now,   // 最後にデータが届いた時刻 [ミリ秒]
    };
    game.players.push(player);
}

// ===== 計測中だけ膨らみを足し込む =====
if (game.phase === "playing" && !player.burst) {
    // 計測が始まる前の時間は数えない
    const from = Math.max(player.lastAt, game.phaseStartedAt);
    const dt = Math.min(Math.max(now - from, 0) / 1000, MAX_DT);
    player.amount += Math.max(p - config.deadzone, 0) * dt;

    // しきい値を超えたら破裂。先に届いた人ほど上位になる
    if (player.amount >= config.threshold) {
        player.burst = true;
        if (game.nextRank <= config.maxRank) {
            player.rank = game.nextRank;
            game.nextRank += 1;
        }
    }
}

player.p = p;
player.lastAt = now;
flow.set("game", game);
return null;

// 0.05秒ごとに動く。ゲームの段階を進めて、全員分の state をブラウザへ送る。
// state の形式はリポジトリ直下の README「Node-RED ↔ ブラウザのメッセージ形式」を参照。
const config = flow.get("config");
const game = flow.get("game");
if (!config || !game) return null;

const now = Date.now();

function setPhase(next) {
    game.phase = next;
    game.phaseStartedAt = now;
}

// ===== 段階の切り替え =====
const elapsed = (now - game.phaseStartedAt) / 1000;
if (game.phase === "countdown" && elapsed >= config.countdownFrom) {
    setPhase("playing");
} else if (game.phase === "playing") {
    const ranksFull = game.nextRank > config.maxRank;
    const allBurst = game.players.length > 0 && game.players.every(function (pl) { return pl.burst; });
    // 順位が決まりきった・全員割れた・制限時間になった のどれかで終了
    if (ranksFull || allBurst || elapsed >= config.timeLimit) {
        setPhase("finished");
    }
}
flow.set("game", game);

// ===== ブラウザに送る state をつくる =====
const t = (now - game.phaseStartedAt) / 1000;
const state = {
    type: "state",
    phase: game.phase,
    countdown: game.phase === "countdown" ? Math.max(1, config.countdownFrom - Math.floor(t)) : null,
    remaining: game.phase === "playing" ? Math.round(Math.max(0, config.timeLimit - t) * 10) / 10 : null,
    players: game.players.map(function (pl) {
        return {
            id: pl.id,
            color: pl.color,
            level: Math.round(Math.min(1, pl.amount / config.threshold) * 1000) / 1000,
            p: Math.round(pl.p * 10) / 10,
            burst: pl.burst,
            rank: pl.rank,
            // 一定時間データが来なければ通信切れ
            online: now - pl.lastAt <= config.offlineMs,
        };
    }),
};

const online = state.players.filter(function (pl) { return pl.online; }).length;
node.status({ fill: "blue", shape: "dot", text: game.phase + " / 接続 " + online + "人" });

// 新しい msg で送る（ブラウザごとの _session を持たないので、つないでいる全員に届く）
return { payload: JSON.stringify(state) };

// ブラウザのボタン操作を受け付ける。受け付けない段階で届いた操作は無視する。
//   {"type":"start"} … 待機中だけ。カウントダウンを始める（終わったら「段階を進めて〜」が計測を始める）
//   {"type":"reset"} … いつでも。膨らみ・順位を消して待機に戻す（参加者の一覧は残す）
const game = flow.get("game");
if (!game) return null;

const type = msg.payload && msg.payload.type;

if (type === "start" && game.phase === "waiting") {
    game.phase = "countdown";
    game.phaseStartedAt = Date.now();
} else if (type === "reset") {
    game.players.forEach(function (pl) {
        pl.amount = 0;
        pl.burst = false;
        pl.rank = null;
    });
    game.nextRank = 1;
    game.phase = "waiting";
    game.phaseStartedAt = Date.now();
}

flow.set("game", game);
return null;

// /balloon/<ファイル名> で web/ フォルダのファイルを返す。
// web/ の場所は、Node-RED を起動するときの環境変数 BALLOON_WEB_DIR で指定する。
// 返してよいファイルだけをここに並べる（それ以外は 404）
const FILES = {
    "index.html": "text/html; charset=utf-8",
    "style.css": "text/css; charset=utf-8",
    "app.js": "text/javascript; charset=utf-8",
    "mock.js": "text/javascript; charset=utf-8",
};

const file = msg.req.params.file || "index.html";
const urlPath = msg.req.originalUrl.split("?")[0];

// /balloon（末尾の / なし）だと CSS・JS の相対パスがずれるので、/balloon/ に転送する
if (!msg.req.params.file && !urlPath.endsWith("/")) {
    msg.statusCode = 301;
    msg.headers = { Location: "balloon/" };
    msg.payload = "";
    return [null, msg];
}

if (!FILES[file]) {
    msg.statusCode = 404;
    msg.headers = { "Content-Type": "text/plain; charset=utf-8" };
    msg.payload = "ファイルが見つかりません: " + file;
    return [null, msg];
}

const webDir = env.get("BALLOON_WEB_DIR");
if (!webDir) {
    msg.statusCode = 500;
    msg.headers = { "Content-Type": "text/plain; charset=utf-8" };
    msg.payload = "環境変数 BALLOON_WEB_DIR に web フォルダの場所を設定してから Node-RED を起動してください（node-red/README.md を参照）";
    node.warn(msg.payload);
    return [null, msg];
}

msg.filename = webDir.replace(/[\\/]+$/, "") + "/" + file;
// 編集した web/ のファイルがすぐ反映されるよう、ブラウザにキャッシュさせない
msg.headers = { "Content-Type": FILES[file], "Cache-Control": "no-cache" };
return [msg, null];

// web/ のファイルが読めなかった（BALLOON_WEB_DIR の場所が違う など）ときに 500 を返す
msg.statusCode = 500;
msg.headers = { "Content-Type": "text/plain; charset=utf-8" };
msg.payload = "ファイルを読めませんでした: " + msg.filename + "\nBALLOON_WEB_DIR の場所を確認してください";
return msg;
